import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Chartink Integration","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/chartink-integration.md","filePath":"new-features/chartink-integration.md"}'),d={name:"new-features/chartink-integration.md"};function n(i,e,s,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="chartink-integration" tabindex="-1">Chartink Integration <a class="header-anchor" href="#chartink-integration" aria-label="Permalink to &quot;Chartink Integration&quot;">​</a></h1><p>Tradeboard turns a Chartink scanner alert into orders. Configure the strategy at <code>/chartink</code>, point the Chartink alert at the strategy&#39;s webhook URL, and every scan that fires places orders for the symbols it returns.</p><h2 id="how-a-scan-becomes-an-order" tabindex="-1">How a Scan Becomes an Order <a class="header-anchor" href="#how-a-scan-becomes-an-order" aria-label="Permalink to &quot;How a Scan Becomes an Order&quot;">​</a></h2><p>The action is read from the <strong>scan name</strong>, not from the payload. The name must contain one of four keywords:</p><table tabindex="0"><thead><tr><th>Keyword in scan name</th><th>Action sent</th><th>Order type</th><th>Treated as</th></tr></thead><tbody><tr><td><code>BUY</code></td><td>BUY</td><td><code>placeorder</code></td><td>Entry</td></tr><tr><td><code>SHORT</code></td><td>SELL</td><td><code>placeorder</code></td><td>Entry</td></tr><tr><td><code>SELL</code></td><td>SELL</td><td><code>placesmartorder</code> with <code>position_size: 0</code></td><td>Exit</td></tr><tr><td><code>COVER</code></td><td>BUY</td><td><code>placesmartorder</code> with <code>position_size: 0</code></td><td>Exit</td></tr></tbody></table><p>A scan name containing none of these is rejected with HTTP 400.</p><p>Exits use a smart order with a zero target position, so the broker&#39;s own net position decides the exit quantity. You do not have to track how much is open.</p><h2 id="dual-queue-and-rate-limiting" tabindex="-1">Dual Queue and Rate Limiting <a class="header-anchor" href="#dual-queue-and-rate-limiting" aria-label="Permalink to &quot;Dual Queue and Rate Limiting&quot;">​</a></h2><p>Orders do not go to the broker straight from the webhook. They are queued and drained by a background worker:</p><ul><li>Entry orders (<code>BUY</code>, <code>SHORT</code>) go to the regular queue and are released at up to 10 per second.</li><li>Exit orders (<code>SELL</code>, <code>COVER</code>) go to the smart-order queue, which is drained first and paced at one per second.</li></ul><p>Exits therefore take priority over entries when both arrive in the same scan.</p><p>The webhook route itself is rate-limited by <code>WEBHOOK_RATE_LIMIT</code>, which defaults to 100 requests per minute.</p><h2 id="strategy-configuration" tabindex="-1">Strategy Configuration <a class="header-anchor" href="#strategy-configuration" aria-label="Permalink to &quot;Strategy Configuration&quot;">​</a></h2><p>Each strategy holds its own symbol list. Per symbol you configure the exchange, quantity, and product type. Chartink strategies are <strong>cash-market only</strong>: the valid exchanges are <code>NSE</code> and <code>BSE</code>, and the product type is <code>MIS</code> for intraday or <code>CNC</code> for delivery.</p><p>Symbols can be added one at a time or pasted in bulk as <code>SYMBOL,EXCHANGE,QUANTITY,PRODUCT</code> lines.</p><p>A symbol returned by the scan but absent from the strategy&#39;s mapping is skipped.</p><h2 id="trading-hours-and-auto-square-off" tabindex="-1">Trading Hours and Auto Square-off <a class="header-anchor" href="#trading-hours-and-auto-square-off" aria-label="Permalink to &quot;Trading Hours and Auto Square-off&quot;">​</a></h2><p>An intraday strategy has three times, all IST:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td>Start time</td><td>Nothing is placed before this, entries or exits</td></tr><tr><td>End time</td><td>Entry orders (<code>BUY</code>, <code>SHORT</code>) are refused after this</td></tr><tr><td>Square-off time</td><td>Nothing is placed after this, and a scheduled job flattens every mapped symbol</td></tr></tbody></table><p>The square-off job issues a smart order with <code>quantity: 0</code> and <code>position_size: 0</code> for each mapped symbol, queued like any other order so the pacing still applies.</p><p>Positional strategies skip all three checks.</p><h2 id="setting-up-the-alert" tabindex="-1">Setting Up the Alert <a class="header-anchor" href="#setting-up-the-alert" aria-label="Permalink to &quot;Setting Up the Alert&quot;">​</a></h2><ol><li>Create the strategy at <code>/chartink</code> and add its symbols.</li><li>Copy the generated webhook URL.</li><li>In Chartink, create the scan and name it so the name contains <code>BUY</code>, <code>SELL</code>, <code>SHORT</code>, or <code>COVER</code>.</li><li>Set the alert&#39;s webhook to the copied URL.</li><li>Activate the strategy in Tradeboard. An inactive strategy accepts the webhook and does nothing.</li></ol><p>Test in Analyzer mode first. Chartink orders use the same service layer as the REST API, so Analyzer mode and Action Center approval apply to them exactly as they do to an API order.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./strategy-rms-engine.html">Strategy RMS Engine</a> for the separate <code>/strategy</code> webhook used by alert senders. Batch strategies accept <code>start</code> and <code>stop</code>; signal strategies accept <code>long_entry</code>, <code>long_exit</code>, <code>short_entry</code>, and <code>short_exit</code> from the JSON payload. Chartink remains a separate integration that derives its action from the scan name.</li><li><a href="./../trading-platform/chartink.html">ChartInk</a> for the platform-side setup.</li></ul>',26)])])}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
